#include "codegen_internal.h"
/* the `&.` proc call currently being emitted inside its own nil guard */
static int g_sn_proc_node = -1;

/* The call whose poly-hash face is being re-emitted, so the arm that installs
   the face does not fire again on its own substituted receiver. */
/* The C type of a bound Method's self slot as the target reads it. A
   `__bam_` wrapper over a value receiver (`0.method(:+)`,
   `false.method(:to_s)`) declares __bam_r as that value's type, and the call
   through the Method has to say so: on wasm the C compiler wraps a direct
   call whose pointer type disagrees with the callee's in a thunk, and where
   it cannot convert (a bool from a pointer) the thunk traps
   (`bitcast_invalid`). Everything else takes `void *`, which is what the
   slot holds. */
static const char *bm_self_ctype(Scope *tm, int shift) {
  if (!tm || shift != 1 || tm->nparams < 1 || !tm->pnames[0] || strcmp(tm->pnames[0], "__bam_r") != 0) return "void *";
  LocalVar *pp = scope_local(tm, tm->pnames[0]);
  if (!pp) return "void *";
  if (pp->type == TY_BOOL) return "sp_bool";
  if (pp->type == TY_INT) return "sp_int";
  if (pp->type == TY_SYMBOL) return "sp_sym";
  return "void *";
}

static int g_pp_hash_node = -1;
/* Recursion guard for the boxed-handle face re-entry, the same shape as
   g_pp_hash_node: the re-emission asks the inference again, and a type cache
   is not a recursion guard. */
static int g_handle_face_node = -1;

const int *call_args(const NodeTable *nt, int id, int *argc) {
  *argc = 0;
  int args = nt_ref(nt, id, "arguments");
  return args >= 0 ? nt_arr(nt, args, "arguments", argc) : NULL;
}


/* Rewrite a printf format that uses named references into a positional one.
   `%<name>SPEC` -> `%SPEC`, `%{name}` -> `%s` (Ruby's to_s of the value), `%%`
   stays. The referenced names (in order) are collected into names[]/name_len[]
   (capacity maxn). Returns the ref count, or -1 (caller falls through) when the
   format has no named reference, more than maxn of them, a name too long for
   the caller's buffer, or a mix of named and positional specifiers (which Ruby
   rejects). */
/* Unbox a POLY-returning call into a scalar slot. What the method returned is
   only known at run time -- an Integer that grew into a Bignum reads back as a
   pointer through a bare `.v.i` -- so convert rather than reinterpret. */
static void emit_unbox_poly_ret(Compiler *c, TyKind slot, const char *expr, Buf *b) {
  if (slot == TY_INT)   { buf_printf(b, "sp_poly_to_i(%s)", expr); return; }
  if (slot == TY_FLOAT) { buf_printf(b, "sp_poly_to_f(%s)", expr); return; }
  emit_unbox_text(c, slot, expr, b);
}

static int parse_named_format(const char *fmt, Buf *rew, const char **names,
                              int *name_len, int maxn) {
  int n = 0, has_named = 0, has_positional = 0;
  for (const char *p = fmt; *p; ) {
    if (*p != '%') { buf_putn(rew, p, 1); p++; continue; }
    if (p[1] == '%') { buf_puts(rew, "%%"); p += 2; continue; }
    if (p[1] == '<' || p[1] == '{') {
      char close = p[1] == '<' ? '>' : '}';
      const char *e = strchr(p + 2, close);
      if (!e) { buf_putn(rew, p, 1); p++; continue; }
      int len = (int)(e - (p + 2));
      /* the caller copies the name into a fixed char[128]; reject a longer name
         rather than silently truncating it to the wrong symbol. */
      if (n >= maxn || len >= 128) return -1;
      /* keep the delimiter with the name: CRuby's KeyError message quotes the
         form the format used ("key{a}" vs "key<a>") */
      names[n] = p + 1; name_len[n] = len + 2; n++;
      has_named = 1;
      p = e + 1;
      if (close == '}') { buf_puts(rew, "%s"); continue; }  /* %{name} -> to_s */
      buf_puts(rew, "%");
      while (*p && !strchr("diouxXeEfgGscbB", *p)) { buf_putn(rew, p, 1); p++; }  /* flags/width/prec */
      if (*p) { buf_putn(rew, p, 1); p++; }  /* conversion char */
      continue;
    }
    has_positional = 1;
    buf_putn(rew, p, 1); p++;
  }
  /* Ruby raises ArgumentError on a mix of named and positional specifiers; bail
     so the caller falls back rather than emitting misaligned arguments. */
  if (has_named && has_positional) return -1;
  return has_named ? n : -1;
}

/* A regexp's encoding is US-ASCII when its source is 7-bit clean (the common
   case), else UTF-8. Spinel is ASCII/UTF-8 only, so this covers the supported
   domain; fixed_encoding? is true exactly when the encoding is not US-ASCII. */
static int re_src_all_ascii(const char *s) {
  if (!s) return 1;
  for (; *s; s++) if ((unsigned char)*s >= 0x80) return 0;
  return 1;
}

/* A backreference (\1..\9, \k<name>, \g<name>) defeats the linear-time matcher,
   so Regexp.linear_time? is false for such a pattern and true otherwise. */
static int re_src_has_backref(const char *s) {
  if (!s) return 0;
  /* Inside a [...] character class a `\1` is an octal escape and `\k`/`\g` are
     literal, none of them backreferences. Track class membership (classes do
     not nest; the first `]` closes) so those don't false-positive. */
  int in_class = 0;
  for (; *s; s++) {
    if (*s == '\\' && s[1]) {
      char n = s[1];
      if (!in_class && ((n >= '1' && n <= '9') || n == 'k' || n == 'g')) return 1;
      s++;  /* skip the escaped char (in or out of a class) */
      continue;
    }
    if (in_class) { if (*s == ']') in_class = 0; }
    else if (*s == '[') in_class = 1;
  }
  return 0;
}

int emit_ctor_yield_inline(Compiler *c, int id, int ci, Buf *b) {
  const NodeTable *nt = c->nt;
  int block = nt_ref(nt, id, "block");
  /* A literal BlockNode is spliced directly. A forwarded `&b` / `&`
     (BlockArgumentNode) inside an inlined enclosing method resolves to that
     method's own block, which is exactly the currently-active g_block_id -- so
     inherit it rather than bailing (which would fall back to the plain
     constructor and SKIP the yielding initialize, leaving its ivars unset and
     later dereferenced as NULL) (#3209). block < 0 is the no-block construction:
     still inline the yielding initialize body so its ivar writes run -- the
     emitted constructor skips a yielding initialize, so without this the body
     (including @ivar = ...) would vanish. With g_block_id < 0 a `yield` is dead
     code and `block_given?` folds to false, matching a blockless `new`. */
  int fwd_block = 0;
  if (block >= 0 && nt_type(nt, block) && sp_streq(nt_type(nt, block), "BlockArgumentNode")) {
    /* only inheritable when an enclosing block is actually in scope (an inlined
       method's forwarded block); with none live there is nothing to yield to and
       the plain-constructor fallback is correct. */
    if (g_block_id < 0) return 0;
    fwd_block = 1;
  }
  else if (block >= 0 && (!nt_type(nt, block) || !sp_streq(nt_type(nt, block), "BlockNode"))) return 0;
  int mi = comp_method_in_chain(c, ci, "initialize", NULL);
  if (mi < 0 || !c->scopes[mi].yields) return 0;
  Scope *m = &c->scopes[mi];
  if (g_nren + m->nlocals >= MAX_RENAME) return 0;
  for (int i = 0; i < m->nlocals; i++) {
    LocalVar *lv = &m->locals[i];
    if (m->blk_param && lv->name && sp_streq(lv->name, m->blk_param)) continue;
    if (!is_scalar_ret(lv->type)) return 0;
  }

  int tag = ++g_tmp;
  int saved_nren = g_nren, saved_block = g_block_id;
  int saved_bnren = g_block_nren, saved_yfbn = g_yield_block_fallback_nren;
  const char *saved_self = g_self;
  const char *saved_self_deref = g_self_deref;
  int saved_emcls = g_emitting_class_id;
  const char *saved_bpn = g_block_param_name;
  int saved_yfb = g_yield_block_fallback;
  int is_val = c->classes[ci].is_value_type;
  /* stack-local: this ctor inliner recurses (a constructor's block may itself
     construct), and g_self points into this buffer -- a shared static would be
     clobbered by the nested inline. */
  char selfbuf[320];   /* a class name plus a cast: 64 truncated the longest of them */
  g_yield_block_fallback = saved_block;
  g_yield_block_fallback_nren = saved_bnren;
  /* the block being captured is caller code: record the caller's self so
     emit_block_invoke can restore it around the spliced block body. Aliasing
     g_self by pointer is safe now that selfbuf is stack-local: it names an
     ancestor frame's selfbuf, which stays live and unmodified for the whole
     nested emission (a frame only ever writes its own selfbuf). */
  const char *saved_self_fb = g_yield_self_fallback;
  const char *saved_deref_fb = g_yield_self_deref_fallback;
  int saved_emcls_fb = g_yield_emitting_class_fallback;
  const char *saved_self_fb2 = g_yield_self_fallback2;
  const char *saved_deref_fb2 = g_yield_self_deref_fallback2;
  int saved_emcls_fb2 = g_yield_emitting_class_fallback2;
  if (!fwd_block) {
    /* a literal block runs under this call site's self; the block that was
       current keeps its own self one level out (see codegen_iter.c) */
    g_yield_self_fallback2 = saved_self_fb;
    g_yield_self_deref_fallback2 = saved_deref_fb;
    g_yield_emitting_class_fallback2 = saved_emcls_fb;
    g_yield_self_fallback = g_self;
    g_yield_self_deref_fallback = g_self_deref;
    g_yield_emitting_class_fallback = g_emitting_class_id;
  }
  g_block_id = fwd_block ? saved_block : block;
  g_block_nren = fwd_block ? saved_bnren : saved_nren;
  g_block_param_name = m->blk_param;

  int st = ++g_tmp;
  buf_puts(b, "({\n");
  emit_indent(b, g_indent + 1);
  /* A value-type class returns sp_X by value from sp_X_new; a heap class returns
     sp_X *. The inlined body reaches its ivars through g_self + g_self_deref, so
     match the deref to the storage: "." for a value-type local, "->" for a
     pointer. */
  /* the body is spliced below, so only the allocation: sp_X_new would run
     it a second time through the clone */
  buf_printf(b, "sp_%s %s_t%d = sp_%s_new%s(", c->classes[ci].c_name, is_val ? "" : "*", st,
             c->classes[ci].c_name, ctor_init_proc_form(c, ci) >= 0 ? "_noinit" : "");
  emit_args_filled(c, mi, nt_ref(nt, id, "arguments"), "", b);
  buf_puts(b, ");\n");
  /* The constructor rooted the fresh object for its own extent only: it
     returns before the inlined body below runs, and that body allocates (an
     ivar's `[]`, a push into it). Unrooted across those allocations the object
     is swept out from under its own initializer and the writes land in freed
     memory -- `Set[1, 2]` came out as `Set[]` under SPINEL_GC_STRESS=1, and a
     longer program crashed. A value-type class has nothing to root: its
     constructor answers the value itself. */
  if (!is_val) { emit_indent(b, g_indent + 1); buf_printf(b, "SP_GC_ROOT(_t%d);\n", st); }
  snprintf(selfbuf, sizeof selfbuf, "_t%d", st);
  g_self = selfbuf;
  g_self_deref = is_val ? "." : "->";
  int din = g_indent + 1;

  /* declare the initialize body's locals under renamed names */
  for (int i = 0; i < m->nlocals; i++) {
    LocalVar *lv = &m->locals[i];
    if (m->blk_param && lv->name && sp_streq(lv->name, m->blk_param)) continue;
    snprintf(g_ren_from[g_nren], sizeof g_ren_from[0], "%s", lv->name);
    snprintf(g_ren_to[g_nren], sizeof g_ren_to[0], "_y%d_%s", tag, lv->name);
    const char *rn = g_ren_to[g_nren];
    g_nren++;
    emit_inlined_local_decl(c, lv, rn, b, din);
  }

  /* bind params to the call args (call-site scope: renames off) */
  int args = nt_ref(nt, id, "arguments");
  int argc2 = 0;
  const int *argv2 = args >= 0 ? nt_arr(nt, args, "arguments", &argc2) : NULL;
  /* A trailing keyword-hash arg (a Data class's `new(x: .., y: ..)` into a
     keyword-param initialize) binds each keyword param by name, not by
     position -- otherwise the whole hash lands in the first param's slot. */
  const char *last_ty = argc2 > 0 ? nt_type(nt, argv2[argc2 - 1]) : NULL;
  int kwh = (last_ty && sp_streq(last_ty, "KeywordHashNode")) ? argv2[argc2 - 1] : -1;
  int pos_argc = kwh >= 0 ? argc2 - 1 : argc2;
  for (int i = 0; i < m->nparams; i++) {
    emit_indent(b, din);
    { char rn[128]; snprintf(rn, sizeof rn, "_y%d_%s", tag, m->pnames[i]);
      emit_inlined_param_target(c, m, m->pnames[i], rn, b); }
    /* A param past the rest binds by name, never positionally. */
    int past_rest = m->rest_idx >= 0 && i > m->rest_idx;
    int provided = (i < pos_argc && !past_rest) ? argv2[i] : -1;
    /* Only bind from the keyword hash when the param was not already filled
       positionally -- otherwise a same-named key would clobber the positional. */
    if (kwh >= 0 && (i >= pos_argc || past_rest)) {
      int kv = kwh_lookup(nt, kwh, m->pnames[i]);
      if (kv >= 0) provided = kv;
    }
    /* hide THIS inline's renames only: args are call-site expressions,
       and the call site may itself be an outer inlined body whose locals
       are renamed (nested yield-method inlines) -- zeroing the whole
       table emitted the unrenamed lv_<name> (undeclared identifier, or a
       silent capture of a same-named caller local). */
    int sv = g_nren;
    /* A nested inline INSIDE an argument expression pushes its own entries at
       this very depth and overwrites this one's, so restoring the count alone
       brought back another method's names -- the body then emitted the
       unrenamed `lv_<name>` for whatever had been clobbered, which nothing
       declares (`Set.new(set.map { ... })`, #3943). Park the entries across
       the argument, not just the count. */
    int park_n = sv - saved_nren;
    char (*park_f)[96] = NULL; char (*park_t)[112] = NULL;
    if (park_n > 0) {
      park_f = (char (*)[96])malloc(sizeof(char[96]) * (size_t)park_n);
      park_t = (char (*)[112])malloc(sizeof(char[112]) * (size_t)park_n);
      if (park_f && park_t) {
        memcpy(park_f, g_ren_from + saved_nren, sizeof(char[96]) * (size_t)park_n);
        memcpy(park_t, g_ren_to + saved_nren, sizeof(char[112]) * (size_t)park_n);
      }
      else { free(park_f); free(park_t); park_f = NULL; park_t = NULL; }
    }
    g_nren = saved_nren;
    /* args are CALL-SITE expressions: an ivar arg (`Set.new(@data)`) must
       read the caller's self, not the freshly-allocated instance g_self was
       repointed at for the inlined body */
    const char *svs = g_self, *svd = g_self_deref;
    g_self = saved_self; g_self_deref = saved_self_deref;
    /* A rest param collects the middle arguments into an Array rather than
       taking one of them straight into its slot. */
    if (m->rest_idx >= 0 && i == m->rest_idx)
      emit_rest_pack_kwh(c, i, pos_argc - m->npost_rest, argv2, -1, b);
    else if (m->rest_idx >= 0 && i > m->rest_idx && i <= m->rest_idx + m->npost_rest) {
      int post_j = i - m->rest_idx - 1;   /* 0-based index among the posts */
      int argv_idx = pos_argc - m->npost_rest + post_j;
      emit_arg_or_default(c, m, i,
                          (argv2 && argv_idx >= 0 && argv_idx < pos_argc) ? argv2[argv_idx] : -1, b);
    }
    else emit_arg_or_default(c, m, i, provided, b);
    g_self = svs; g_self_deref = svd;
    g_nren = sv;
    if (park_f && park_t) {
      memcpy(g_ren_from + saved_nren, park_f, sizeof(char[96]) * (size_t)park_n);
      memcpy(g_ren_to + saved_nren, park_t, sizeof(char[112]) * (size_t)park_n);
    }
    free(park_f); free(park_t);
    buf_puts(b, ";\n");
  }

  /* The inlined `initialize` body runs in the CONSTRUCTED class's context:
     an implicit-self call inside it (`setup` in `def initialize; setup;
     yield self; end`) must resolve against `ci`, not the caller's class.
     Args above were bound in the caller's context (g_self temporarily
     restored per arg; g_emitting_class_id untouched until here), and the
     spliced block body restores the caller's class via the fallback. */
  g_emitting_class_id = ci;
  int save_ind = g_indent; g_indent = din;
  emit_stmts(c, m->body, b, din);
  g_indent = save_ind;
  emit_indent(b, g_indent + 1);
  buf_printf(b, "_t%d;\n", st);
  emit_indent(b, g_indent); buf_puts(b, "})");

  g_nren = saved_nren;
  g_block_id = saved_block;
  g_block_nren = saved_bnren;
  g_yield_block_fallback_nren = saved_yfbn;
  g_self = saved_self;
  g_self_deref = saved_self_deref;
  g_emitting_class_id = saved_emcls;
  g_block_param_name = saved_bpn;
  g_yield_block_fallback = saved_yfb;
  g_yield_self_fallback = saved_self_fb;
  g_yield_self_fallback2 = saved_self_fb2; g_yield_self_deref_fallback2 = saved_deref_fb2;
  g_yield_emitting_class_fallback2 = saved_emcls_fb2;
  g_yield_self_deref_fallback = saved_deref_fb;
  g_yield_emitting_class_fallback = saved_emcls_fb;
  return 1;
}

static void emit_cmethod_block_arg(Compiler *c, int id, Scope *cm, int blk_tmp, Buf *b);
static void emit_ctor_block_slot(Compiler *c, int id, int initm, const char *lead, Buf *b);

/* Emit `node` as a `sp_Bigint *` for a mixed bigint operand (arithmetic or
   comparison where the other side is bigint): a bigint stays itself, a poly is
   narrowed with sp_poly_as_bigint, and anything else (a plain int) is promoted
   with sp_bigint_new_int. Not for the int64 exponent/shift argument of pow or
   the shift operators, which stays an int. */
void emit_bigint_operand_ext(Compiler *c, int node, Buf *b);
/* An operand a bigint comparison may coerce: another number, or a value whose
   type is only known at run time. A user OBJECT is not one -- its own #== (or
   #<=>) has to dispatch, and coercing the pointer through sp_bigint_new_int
   compared the address instead, silently (#3975). */
static int bigint_cmp_operand_ok(TyKind t) {
  return t == TY_INT || t == TY_BIGINT || t == TY_FLOAT || t == TY_RATIONAL ||
         t == TY_POLY || t == TY_UNKNOWN;
}
/* A FLOAT against a BIGINT compares as doubles -- which is what the runtime's
   own sp_poly_cmp does for the same pair, so the two paths agree. Coercing the
   float into a bigint truncated it to int64 and saturated there, so
   `1.0 / 0 > 10 ** 100` answered false (and the conversion warned). */
static int emit_float_bigint_cmp(Compiler *c, int recv, int arg, const char *op, Buf *b) {
  TyKind lt = comp_ntype(c, recv), rt2 = comp_ntype(c, arg);
  if (!((lt == TY_FLOAT && rt2 == TY_BIGINT) || (lt == TY_BIGINT && rt2 == TY_FLOAT)))
    return 0;
  /* equality is decided exactly: 1.0e100 and 10 ** 100 differ by an ulp, and
     as doubles they would compare equal */
  if (sp_streq(op, "==") || sp_streq(op, "!=")) {
    buf_printf(b, "(%ssp_bigint_eq_f(", sp_streq(op, "!=") ? "!" : "");
    emit_expr(c, lt == TY_BIGINT ? recv : arg, b);
    buf_puts(b, ", ");
    emit_expr(c, lt == TY_BIGINT ? arg : recv, b);
    buf_puts(b, "))");
    return 1;
  }
  buf_puts(b, "(");
  if (lt == TY_BIGINT) { buf_puts(b, "sp_bigint_to_double("); emit_expr(c, recv, b); buf_puts(b, ")"); }
  else emit_expr(c, recv, b);
  buf_printf(b, " %s ", op);
  if (rt2 == TY_BIGINT) { buf_puts(b, "sp_bigint_to_double("); emit_expr(c, arg, b); buf_puts(b, ")"); }
  else emit_expr(c, arg, b);
  buf_puts(b, ")");
  return 1;
}
static void emit_bigint_operand(Compiler *c, int node, Buf *b) {
  TyKind t = comp_ntype(c, node);
  if (t == TY_BIGINT) { emit_expr(c, node, b); return; }
  if (t == TY_POLY) { buf_puts(b, "sp_poly_as_bigint("); emit_expr(c, node, b); buf_puts(b, ")"); return; }
  /* A nilable int carries nil as SP_INT_NIL, and sp_bigint_new_int made a
     Bignum of INT64_MIN out of it: `return (if false then 1 end)` from a
     method whose value is a Bignum answered -9223372036854775808 rather
     than nil, silently (#4800). The guard is only for a value that CAN be
     nil -- a plain Integer of INT64_MIN is a real value and must convert. */
  if (t == TY_INT && call_returns_nullable_int(c, node)) {
    int tv = ++g_tmp;
    buf_printf(b, "({ sp_int _t%d = ", tv);
    emit_expr(c, node, b);
    buf_printf(b, "; _t%d == SP_INT_NIL ? NULL : sp_bigint_new_int(_t%d); })", tv, tv);
    return;
  }
  buf_puts(b, "sp_bigint_new_int("); emit_expr(c, node, b); buf_puts(b, ")");
}
/* Same, reachable from the other emitters (the ivar op-assign). */
void emit_bigint_operand_ext(Compiler *c, int node, Buf *b) { emit_bigint_operand(c, node, b); }

/* Emit re_compile's internal-flag argument from Regexp.new/compile's optional
   second argument: an Integer of public option bits (translated), a truthy
   value meaning IGNORECASE, or absent meaning no flags (#3055). */
static void emit_re_opts_flags(Compiler *c, int argc, const int *argv, Buf *out) {
  if (argc < 2) { buf_puts(out, "0"); return; }
  TyKind ot = comp_ntype(c, argv[1]);
  if (ot == TY_INT) {
    /* a NILABLE Integer slot: `Regexp.new(s, h[:missing])` is CRuby's nil
       options, i.e. none. The sentinel is INTPTR_MIN, whose low three bits
       are clear, so sp_re_opts_to_flags already translates it to no flags --
       it must reach that arm rather than be refused as a conversion (#4896). */
    buf_puts(out, "sp_re_opts_to_flags("); emit_int_expr_nilable(c, argv[1], out); buf_puts(out, ")");
  }
  else if (ot == TY_BOOL) {
    /* internal RE_FLAG_IGNORECASE == 1 */
    buf_puts(out, "(("); emit_expr(c, argv[1], out); buf_puts(out, ") ? 1u : 0u)");
  }
  else if (ot == TY_STRING) {
    /* a String carries flag LETTERS, not a truthy value: "x" is EXTENDED */
    buf_puts(out, "sp_re_opts_from_str("); emit_str_expr(c, argv[1], out); buf_puts(out, ")");
  }
  else {
    /* The type is not known here, so the choice is made where the value is:
       an Integer is option bits and anything else truthy is IGNORECASE, which
       is what CRuby decides from the value too. Settling on the truthy arm
       read every Integer as IGNORECASE, so an option that reached this arm --
       a block parameter, a hash read, anything the analyzer left poly --
       answered /i whatever it held. */
    buf_puts(out, "sp_re_opts_from_poly("); emit_boxed(c, argv[1], out); buf_puts(out, ")");
  }
}

/* `s[i]` on a string with a single non-negative-style int index. Records the
   string receiver and index nodes. Used to fold `s[i] == "c"` into a raw byte
   comparison (no per-access 1-char string allocation). */
static int str_index1(Compiler *c, int node, int *out_recv, int *out_idx) {
  const NodeTable *nt = c->nt;
  const char *ty = nt_type(nt, node);
  if (!ty || !sp_streq(ty, "CallNode")) return 0;
  const char *nm = nt_str(nt, node, "name");
  if (!nm || (!sp_streq(nm, "[]") && !sp_streq(nm, "slice"))) return 0;
  if (nt_ref(nt, node, "block") >= 0) return 0;
  int recv = nt_ref(nt, node, "receiver");
  if (recv < 0 || comp_ntype(c, recv) != TY_STRING) return 0;
  int args = nt_ref(nt, node, "arguments");
  int an = 0;
  const int *av = args >= 0 ? nt_arr(nt, args, "arguments", &an) : NULL;
  if (an != 1 || comp_ntype(c, av[0]) != TY_INT) return 0;
  *out_recv = recv;
  *out_idx = av[0];
  return 1;
}

/* A bare single-byte string literal, e.g. `"{"`. */
static int single_byte_lit(Compiler *c, int node, unsigned char *out) {
  const char *ty = nt_type(c->nt, node);
  if (!ty || !sp_streq(ty, "StringNode")) return 0;
  const char *s = nt_str(c->nt, node, "unescaped");
  if (!s) s = nt_str(c->nt, node, "content");
  if (!s || s[0] == '\0' || s[1] != '\0') return 0;
  *out = (unsigned char)s[0];
  return 1;
}

/* Emit `s[i] == "c"` / `!=` as a raw byte compare when one operand is a
   single-char string index and the other a single-byte literal. The index is
   guarded against negatives (Ruby `s[-1]` indexes from the end) by falling
   back to the general path. Returns 1 if it emitted the optimized form. */
static int emit_strchar_cmp(Compiler *c, int recv, int arg, int eq, Buf *b) {
  int sr, si;
  unsigned char ch;
  int ok = (str_index1(c, recv, &sr, &si) && single_byte_lit(c, arg, &ch)) ||
           (str_index1(c, arg, &sr, &si) && single_byte_lit(c, recv, &ch));
  if (!ok) return 0;
  /* The byte at offset i is the CHARACTER at index i only while every
     character before i is one byte wide, so the raw load is guarded by the
     receiver's fixed-width bit (an ASCII-only or binary string). Without the
     guard `"說*.rb"[1] == "*"` compared the second byte of the first
     character and answered false (#4239). A string that is not fixed width, a
     negative index (which counts from the end), and an index past the end
     (nil, equal to nothing) all take the general path, which is what this
     compiled to before the fold existed. */
  int ts = ++g_tmp, ti = ++g_tmp, tb = ++g_tmp;
  buf_printf(b, "({ const char *_t%d = ", ts);
  if (!emit_strbuf_read_ref(c, sr, b)) emit_expr(c, sr, b);
  buf_printf(b, "; sp_int _t%d = (sp_int)(", ti);
  emit_expr(c, si, b);
  buf_printf(b, "); size_t _t%d; %s(_t%d >= 0 && sp_str_fixed_width(_t%d, &_t%d)"
                " ? (_t%d < (sp_int)_t%d && (unsigned char)_t%d[_t%d] == %u)"
                " : sp_str_eq_cstr(sp_str_char_at_or_nil(_t%d, _t%d), \"\\%03o\")); })",
             tb, eq ? "" : "!", ti, ts, tb, ti, tb, ts, ti, (unsigned)ch,
             ts, ti, (unsigned)ch);
  return 1;
}

/* Does `node` (an instance_exec body subtree) contain a break/next that binds
   to the splice itself -- i.e. not consumed by a nested loop or block? */
static int ie_body_has_break_next(Compiler *c, int node) {
  const NodeTable *nt = c->nt;
  if (node < 0) return 0;
  const char *ty = nt_type(nt, node);
  if (!ty) return 0;
  if (sp_streq(ty, "BreakNode") || sp_streq(ty, "NextNode")) return 1;
  /* constructs that bind their own break/next */
  if (sp_streq(ty, "WhileNode") || sp_streq(ty, "UntilNode") || sp_streq(ty, "ForNode") ||
      sp_streq(ty, "BlockNode") || sp_streq(ty, "LambdaNode") || sp_streq(ty, "DefNode") ||
      sp_streq(ty, "ClassNode") || sp_streq(ty, "ModuleNode")) return 0;
  int nr = nt_num_refs(nt, node);
  for (int i = 0; i < nr; i++) if (ie_body_has_break_next(c, nt_ref_at(nt, node, i))) return 1;
  int na = nt_num_arrs(nt, node);
  for (int i = 0; i < na; i++) { int n = 0; const int *ids = nt_arr_at(nt, node, i, &n); for (int k = 0; k < n; k++) if (ie_body_has_break_next(c, ids[k])) return 1; }
  return 0;
}

/* Iterators whose normal return value is the receiver (Ruby returns self) and
   that have no value-producing emitter -- the valued-break wrapper emits these
   as a statement and uses the receiver as the no-break result. */
static int brk_iter_returns_self(const char *name) {
  if (!name) return 0;
  return sp_streq(name, "each") || sp_streq(name, "each_with_index") ||
         sp_streq(name, "each_pair") || sp_streq(name, "each_value") ||
         sp_streq(name, "each_key") || sp_streq(name, "each_entry") ||
         sp_streq(name, "reverse_each");
}

/* A receiver safe to evaluate twice (once by the iterator's loop, once as the
   break wrapper's no-break result): a read with no side effects. A CallNode or
   anything else falls through, so a side-effecting receiver is not duplicated. */
static int brk_recv_is_pure(Compiler *c, int recv) {
  if (recv < 0) return 0;
  const char *t = nt_type(c->nt, recv);
  if (!t) return 0;
  return sp_streq(t, "LocalVariableReadNode") || sp_streq(t, "InstanceVariableReadNode") ||
         sp_streq(t, "ClassVariableReadNode") || sp_streq(t, "GlobalVariableReadNode") ||
         sp_streq(t, "ConstantReadNode") || sp_streq(t, "ConstantPathNode") ||
         sp_streq(t, "SelfNode") || sp_streq(t, "ArrayNode") || sp_streq(t, "HashNode") ||
         sp_streq(t, "RangeNode") || sp_streq(t, "IntegerNode") || sp_streq(t, "FloatNode") ||
         sp_streq(t, "StringNode") || sp_streq(t, "SymbolNode");
}

/* Unify the value type of every splice-bound break/next in `node` (same
   binding rules as ie_body_has_break_next). TY_UNKNOWN if none carry a value.
   Sizes the splice result temp so a `next <poly>` (e.g. an int ivar widened in
   promote mode) is not dropped into a narrower sp_int slot. */
static TyKind ie_splice_value_ty(Compiler *c, int node) {
  const NodeTable *nt = c->nt;
  if (node < 0) return TY_UNKNOWN;
  const char *ty = nt_type(nt, node);
  if (!ty) return TY_UNKNOWN;
  if (sp_streq(ty, "BreakNode") || sp_streq(ty, "NextNode")) {
    int a = nt_ref(nt, node, "arguments"); int an = 0;
    const int *av = a >= 0 ? nt_arr(nt, a, "arguments", &an) : NULL;
    if (an > 0) return comp_ntype(c, av[0]);
    return sp_streq(ty, "NextNode") ? TY_NIL : TY_UNKNOWN;   /* keep in step with ie_block_break_next_ty */
  }
  if (sp_streq(ty, "WhileNode") || sp_streq(ty, "UntilNode") || sp_streq(ty, "ForNode") ||
      sp_streq(ty, "BlockNode") || sp_streq(ty, "LambdaNode") || sp_streq(ty, "DefNode") ||
      sp_streq(ty, "ClassNode") || sp_streq(ty, "ModuleNode")) return TY_UNKNOWN;
  TyKind r = TY_UNKNOWN;
  int nr = nt_num_refs(nt, node);
  for (int i = 0; i < nr; i++) {
    TyKind s = ie_splice_value_ty(c, nt_ref_at(nt, node, i));
    if (s != TY_UNKNOWN) r = (r == TY_UNKNOWN) ? s : ty_unify(r, s);
  }
  int na = nt_num_arrs(nt, node);
  for (int i = 0; i < na; i++) {
    int n = 0; const int *ids = nt_arr_at(nt, node, i, &n);
    for (int k = 0; k < n; k++) {
      TyKind s = ie_splice_value_ty(c, ids[k]);
      if (s != TY_UNKNOWN) r = (r == TY_UNKNOWN) ? s : ty_unify(r, s);
    }
  }
  return r;
}

/* Emit a valid assignment rvalue for an instance_exec block param the caller
   omitted, given its slot type. default_value() is rvalue-safe for scalars,
   pointers, and the compound-literal value types (Range/Time/Complex/Rational),
   but returns "NULL" for an object type -- correct for a heap object, invalid
   for a value-type object whose C type is a struct (`lv = NULL` won't compile).
   Emit a zero compound literal `(sp_Name){0}` in that case. */
static void emit_ie_param_default(Compiler *c, TyKind t, Buf *b) {
  if (ty_is_object(t)) {
    int cid = ty_object_class(t);
    if (cid >= 0 && cid < c->nclasses && c->classes[cid].is_value_type) {
      buf_printf(b, "(sp_%s){0}", c->classes[cid].c_name);
      return;
    }
  }
  buf_puts(b, default_value(t));
}

/* Print "spinel: <file>:<line>: warning: " for node `id` when
   SPINEL_WARN_UNRESOLVED is set, so a call/constant that silently degrades to
   nil/0 (where CRuby would raise or do real work) can be audited. Returns 1
   when a warning line was started -- the caller appends its message + newline.
   Zero runtime/codegen effect: opt-in stderr only. */
/* 1 iff `node` is statically typed as a StringIO object (the native-struct
   class from packages/stringio). */
static int node_is_stringio(Compiler *c, int node) {
  if (node < 0) return 0;
  TyKind t = comp_ntype(c, node);
  return ty_is_object(t) && ty_object_class(t) >= 0 &&
         c->classes[ty_object_class(t)].c_name &&
         sp_streq(c->classes[ty_object_class(t)].c_name, "StringIO");
}

static int warn_unresolved_pos(Compiler *c, int id) {
  if (!getenv("SPINEL_WARN_UNRESOLVED")) return 0;
  const NodeTable *nt = c->nt;
  int ln = (int)nt_int(nt, id, "node_line", 0);
  const char *file = nt->source_file;
  if (ln > 0) {
    const char *f = nt_file_path(nt, (int)nt_int(nt, id, "node_file", 0));
    if (f && *f) file = f;
  }
  if (!file || !*file) file = "source.rb";
  fprintf(stderr, "spinel: %s:%d: warning: ", file, ln);
  return 1;
}

/* A block-carrying call on a POLY receiver whose name an instantiated user
   class also owns as a block-taking method (it yields, or keeps a real &blk).
   The element-loop emitters assume the receiver is a builtin container and
   walk it as one, which answers empty when the value is the user object --
   the mirror of the dispatch dropping the builtin arm. Only the cls_id
   dispatch can serve both, so those emitters decline here and let it. Limited
   to the names the dispatch has a builtin arm for: declining any other would
   trade a wrong answer for a NoMethodError on a container receiver. */
int poly_block_call_needs_dispatch(Compiler *c, int id) {
  const NodeTable *nt = c->nt;
  if (nt_ref(nt, id, "block") < 0) return 0;
  int recv = nt_ref(nt, id, "receiver");
  /* Both views have to say poly. comp_ntype is what the element-loop emitters
     themselves consult, so declining on anything else keeps a Range or a typed
     array on its own path; infer_type is what a_block_is_lifted used to decide
     the capture cells, and a call routed here whose captures analyze left
     uncelled cannot be emitted at all. */
  if (recv < 0 || comp_ntype(c, recv) != TY_POLY ||
      infer_type(c, recv) != TY_POLY) return 0;
  const char *name = nt_str(nt, id, "name");
  if (!poly_enum_op_for(name)) return 0;
  /* A block whose body yields can only be SPLICED: routing it to the dispatch
     lifts it to a standalone proc, where the enclosing method's block is not
     in scope and the yield lowers to a LocalJumpError. That is the shape of a
     yielding method's own body (`@a.each { |x| yield x }`), which is inlined
     at its call sites. A proc form is the exception: there the block is a real
     parameter and the lifted proc captures it. */
  { int blk = nt_ref(nt, id, "block");
    int bb = blk >= 0 ? nt_ref(nt, blk, "body") : -1;
    Scope *es = comp_scope_of(c, id);
    if (bb >= 0 && proc_body_has_yield(c, bb) &&
        !(es && (es->is_proc_form || es->is_lowered_yield))) return 0; }
  for (int k = 0; k < c->nclasses; k++) {
    if (!c->classes[k].instantiated) continue;
    int mi = comp_method_in_chain(c, k, name, NULL);
    if (mi < 0) continue;
    Scope *m = &c->scopes[mi];
    if (m->yields || (m->blk_param && m->blk_param[0])) return 1;
  }
  return 0;
}

/* Whether a `&.` call on a poly receiver has yet to pass through its nil
   guard. The guard re-enters the emission with g_sn_skip set on the node, so
   this answers false on that second pass. */
int sn_guard_pending(Compiler *c, int id) {
  const NodeTable *nt = c->nt;
  if (g_sn_skip == id) return 0;
  const char *op = nt_str(nt, id, "call_operator");
  if (!op || !sp_streq(op, "&.")) return 0;
  int recv = nt_ref(nt, id, "receiver");
  return recv >= 0 && comp_ntype(c, recv) == TY_POLY;
}


/* Neither class is the other, nor an ancestor of the other. Such a pair has no
   conversion: their structs share no prefix by construction. */
static int g_subdispatch_id = -1;   /* the call currently re-entered as poly (#4023) */
static int obj_class_unrelated(Compiler *c, int a, int b) {
  if (a < 0 || b < 0 || a == b) return 0;
  for (int k = c->classes[a].parent; k >= 0; k = c->classes[k].parent) if (k == b) return 0;
  for (int k = c->classes[b].parent; k >= 0; k = c->classes[k].parent) if (k == a) return 0;
  return 1;
}

/* Emit the switch key for a poly method dispatch. An SP_TAG_OBJ value uses its
   real cls_id; a boxed scalar maps to its reopened primitive class index (so a
   reopened Integer/Float/String/Symbol/nil method still dispatches), else to a
   sentinel matching no case -- this keeps a plain scalar (cls_id 0) from
   aliasing a regular user class that happens to occupy index 0. */
/* A builtin-primitive reopen (`class String; def shout; ...`): its instances
   exist without any user constructor, so the `.new` census behind
   `instantiated` never marks it and its dispatch arm must not be dropped for
   that (#4219). Limited to the primitive names the dispatch key below can map
   a runtime tag to. */
static int class_is_prim_reopen(Compiler *c, int k) {
  const char *n = c->classes[k].name;
  return sp_streq(n, "Integer") || sp_streq(n, "Float") ||
         sp_streq(n, "String") || sp_streq(n, "Symbol") ||
         sp_streq(n, "NilClass");
}

/* Whether a user exception class answers `name`: the dispatch key then has
   to map a boxed exception (tagged SP_BUILTIN_EXCEPTION) to its class. */
static int poly_exc_cand(Compiler *c, const char *name) {
  for (int k = 0; k < c->nclasses; k++)
    if (class_is_exc_subclass(c, k) &&
        (comp_method_in_chain(c, k, name, NULL) >= 0 || comp_reader_in_chain(c, k, name, NULL)))
      return 1;
  return 0;
}

static void emit_poly_dispatch_key(Compiler *c, int tv, int cls0_cand, int prim_cand, int exc_cand, Buf *b) {
  if (exc_cand) {
    /* a boxed exception keys by its user class (sp_exc_user_cls_id); every
       other value by the rule below */
    buf_printf(b, "((_t%d.tag == SP_TAG_OBJ && _t%d.cls_id == SP_BUILTIN_EXCEPTION) ? sp_exc_user_cls_id(_t%d) : ", tv, tv, tv);
    emit_poly_dispatch_key(c, tv, cls0_cand, prim_cand, 0, b);
    buf_puts(b, ")");
    return;
  }
  /* Every boxed scalar (int/float/str/sym/nil/bool) carries cls_id 0, which
     aliases the first user class (index 0). When class 0 is a candidate of this
     dispatch -- it defines/inherits the method, so it emits a `case 0:` arm --
     a scalar receiver would wrongly enter that arm and deref its v.p (issue
     #1576: `value.to_s` on a poly int, with a user class 0 defining `to_s`,
     segfaulted). Guard the key so a non-object value maps to a sentinel that
     matches no case and falls through to the default/poly arm. When class 0 is
     not a candidate (no `case 0:` arm), a scalar's cls_id 0 already matches
     nothing, so the plain key is correct -- and cheaper on the hot per-dispatch
     path (optcarrot's per-frame tick), so keep it there. */
  /* With a primitive-reopen candidate in the switch, a scalar receiver has a
     real arm: its tag has to map to that class's index (a boxed scalar's
     cls_id carries nothing). Same mapping promote mode always uses; kept off
     the plain path otherwise, which the hot per-dispatch sites stay on
     (#4219). */
  if (!g_promote_mode && !prim_cand) {
    if (cls0_cand) buf_printf(b, "(_t%d.tag == SP_TAG_OBJ ? _t%d.cls_id : 0x7fffffff)", tv, tv);
    else buf_printf(b, "_t%d.cls_id", tv);
    return;
  }
  static const struct { const char *tag, *cls; } P[] = {
    {"SP_TAG_INT", "Integer"}, {"SP_TAG_FLT", "Float"},
    {"SP_TAG_STR", "String"},  {"SP_TAG_SYM", "Symbol"},
    {"SP_TAG_NIL", "NilClass"},
  };
  buf_printf(b, "(_t%d.tag == SP_TAG_OBJ ? _t%d.cls_id", tv, tv);
  for (unsigned i = 0; i < sizeof P / sizeof P[0]; i++) {
    int idx = comp_class_index(c, P[i].cls);
    if (idx >= 0) buf_printf(b, " : _t%d.tag == %s ? %d", tv, P[i].tag, idx);
  }
  buf_puts(b, " : 0x7fffffff)");
}

/* A poly receiver can hold a Class object at run time. The instance-method
   arms of a poly dispatch must not claim it: when any user class defines a
   class method of this name that the call could reach, route a class-tagged
   value into a class-side switch ahead of the instance switch. Without this a
   class value either raised (no compatible instance arm left the switch
   empty) or entered an instance arm and dereferenced the class token as an
   object pointer -- #4218, the ActionText filter-chain shape, where the raise
   was the polite form and the deref was a SIGSEGV. Emits
   `if (tag == SP_TAG_CLASS) { switch ... } else ` and returns 1 when any arm
   was built; emits nothing and returns 0 otherwise. */
static int cls_arm_takes_argc(Scope *s, int argc);
static int emit_poly_cls_value_prearm(Compiler *c, const char *name, int argc,
                                      const int *atmp, const TyKind *atmp_ty,
                                      int tv, int tr, TyKind ret, Buf *b) {
  int ccls8[64], cmi8[64], nc8 = 0;
  int ncc8 = 0;
  const PolyCand *cc8 = comp_cmethod_candidates(c, name, &ncc8);   /* per name, not per site (#4966) */
  for (int ki = 0; ki < ncc8 && nc8 < 64; ki++) {
    int k = cc8[ki].cls;
    if (is_builtin_reopen(c->classes[k].name)) continue;
    int kmi = cc8[ki].mi;
    if (!scope_has_callable_symbol(c, kmi)) continue;
    Scope *ks = &c->scopes[kmi];
    /* a yielding / block-taking / rest candidate has no arm this emitter can
       fill; such a class falls to the default raise */
    if (ks->yields || (ks->blk_param && ks->blk_param[0]) || ks->rest_idx >= 0)
      continue;
    if (!cls_arm_takes_argc(ks, argc)) continue;
    /* a param and its argument temp both concretely typed but different is a
       hard C error, not a coercion: that class cannot be this call's target */
    int incompat8 = 0;
    for (int a = 0; a < ks->nparams && !incompat8; a++) {
      int slot = arg_slot_for_param(c, ks, a, argc);
      if (slot < 0 || slot >= argc || !atmp_ty) continue;
      LocalVar *pp = ks->pnames && ks->pnames[a] ? scope_local(ks, ks->pnames[a]) : NULL;
      TyKind pt = pp ? pp->type : TY_POLY;
      TyKind at0 = atmp_ty[slot];
      if (pt != TY_POLY && pt != TY_UNKNOWN && at0 != TY_POLY && at0 != TY_UNKNOWN &&
          pt != at0) incompat8 = 1;
    }
    if (incompat8) continue;
    ccls8[nc8] = k; cmi8[nc8] = kmi; nc8++;
  }
  if (nc8 == 0) return 0;
  buf_printf(b, "if (_t%d.tag == SP_TAG_CLASS) { switch (_t%d.cls_id) {", tv, tv);
  for (int i = 0; i < nc8; i++) {
    Scope *ks = &c->scopes[cmi8[i]];
    TyKind kr = (TyKind)ks->ret;
    Buf cb; memset(&cb, 0, sizeof cb);
    emit_method_cname(c, ks, &cb);
    buf_puts(&cb, "(");
    /* the receiving-class token, when the body reads it: the class this arm's
       case selected (#4217) */
    const char *lead = emit_cmethod_self_cls_arg(c, cmi8[i], ccls8[i], &cb);
    for (int a = 0; a < ks->nparams; a++) {
      buf_puts(&cb, a ? ", " : lead);
      LocalVar *pp = ks->pnames && ks->pnames[a] ? scope_local(ks, ks->pnames[a]) : NULL;
      TyKind pt = pp ? pp->type : TY_POLY;
      if (pt == TY_UNKNOWN) pt = TY_POLY;
      int slot = arg_slot_for_param(c, ks, a, argc);
      if (slot >= 0 && slot < argc && atmp) {
        char at[32]; snprintf(at, sizeof at, "_t%d", atmp[slot]);
        TyKind at0 = atmp_ty ? atmp_ty[slot] : TY_POLY;
        /* the temp holds the argument in its own C type; box it up for a poly
           param, hand it raw to a matching one, unbox a poly temp down */
        if (at0 == TY_POLY && pt == TY_POLY) buf_puts(&cb, at);
        else if (at0 == TY_POLY) emit_unbox_text(c, pt, at, &cb);
        else if (pt == TY_POLY) emit_boxed_text(c, at0, at, &cb);
        else buf_puts(&cb, at);
      }
      else emit_arg_or_default(c, ks, a, -1, &cb);
    }
    buf_puts(&cb, ")");
    buf_printf(b, " case %d: ", ccls8[i]);
    if (method_is_void(ks)) buf_puts(b, cb.p ? cb.p : "");
    else {
      buf_printf(b, "_t%d = ", tr);
      if (ret == TY_POLY && kr != TY_POLY) emit_boxed_text(c, kr, cb.p ? cb.p : "", b);
      else if (ret != TY_POLY && kr == TY_POLY) emit_unbox_text(c, ret, cb.p ? cb.p : "", b);
      else buf_puts(b, cb.p ? cb.p : "");
    }
    buf_puts(b, "; break;");
    free(cb.p);
  }
  buf_printf(b, " default: sp_raise_nomethod(sp_nomethod_msg(\"%s\", _t%d)); break;",
             name, tv);
  buf_puts(b, " } }\nelse ");
  return 1;
}

/* Compiler-synthesized instance methods that must stay invisible to
   reflection (respond_to?, instance_methods): they are implementation detail
   with no CRuby counterpart. Matched by exact name so a user-defined `__foo`
   stays visible. */
static int name_is_synth_method(Compiler *c, const char *m) {
  if (!m) return 0;
  if (sp_streq(m, "__enum_to_a")) return 1;
  /* `__inc <n> <name>`: the shadow copy of an included module's method, kept
     so an override can reach it through super (#3738) */
  if (strncmp(m, "__inc ", 6) == 0) return 1;
  /* a parameter default moved into a method of its own
     (desugar_recursive_param_defaults, #4900): known by the mark on its
     DefNode rather than its name, which the desugar picks so that no method
     the program defines has it */
  if (strncmp(m, "__sp_default_", 13) != 0) return 0;
  for (int si = 0; si < c->nscopes; si++) {
    Scope *s = &c->scopes[si];
    if (s->def_node >= 0 && s->name && sp_streq(s->name, m) &&
        nt_int(c->nt, s->def_node, "default_helper", 0)) return 1;
  }
  return 0;
}

/* Enumerable's public instance methods, for respond_to? on a user class
   that includes the module (served through the __enum_to_a redirect). */
int name_is_enumerable_module_method(const char *m) {
  static const char *const em[] = {
    "each", "map", "collect", "select", "filter", "reject", "find",
    "detect", "find_all", "find_index", "reduce", "inject", "to_a",
    "entries", "sort", "sort_by", "min", "max", "min_by", "max_by",
    "minmax", "minmax_by", "sum", "count", "include?", "member?",
    "first", "take", "drop", "take_while", "drop_while", "tally",
    "each_with_index", "each_with_object", "each_slice", "each_cons",
    "each_entry", "flat_map", "collect_concat", "group_by", "partition",
    "zip", "any?", "all?", "none?", "one?", "chunk", "chunk_while",
    "slice_when", "slice_before", "slice_after", "filter_map", "uniq",
    "to_h", "lazy", "cycle", "reverse_each", "to_set", NULL };
  for (int i = 0; em[i]; i++) if (sp_streq(m, em[i])) return 1;
  return 0;
}

/* Can this Integer / Float operand carry the nil sentinel? The #3505 marking
   answers: a local or ivar some write left the sentinel in, a call whose
   return can be it, a missed element read; a literal, an arithmetic result
   or a length never. Its answer is what decides whether a comparison tests
   for the sentinel, so a loop's `i < n` stays a bare compare. */
static int cmp_operand_may_be_nil(Compiler *c, int id) {
  return id >= 0 && nullable_int_value(c, id);
}
/* Comparable's instance methods, for respond_to? on a user class that mixes it
   in (spinel keys the mixin off the presence of a user `<=>`). */
static int name_is_comparable_module_method(const char *m) {
  static const char *const cm[] = {
    "<", ">", "<=", ">=", "==", "between?", "clamp", NULL };
  for (int i = 0; cm[i]; i++) if (sp_streq(m, cm[i])) return 1;
  return 0;
}

