        int boxed_ans = sp_streq(name, "allocate") || sp_streq(name, "keyword_init?");
        const char *cbo = (ret == TY_POLY && !boxed_ans)
                            ? (sp_streq(name, "superclass") ? "sp_box_class(" : "sp_box_poly_array(")
                            : "";
