          if (ret == TY_POLY) buf_puts(b, getx);
          else emit_unbox_text(c, trt, getx, b);
          if (is_fetch) { buf_puts(b, " : "); emit_poly_fetch_absent(c, argc, atmp, argc == 2 ? argv[1] : -1, argv[0], ret, trt, b); }
