        int tf = ++g_tmp;
        buf_printf(b, "({ sp_float _t%d = ", tf); emit_expr(c, av[0], b);
        buf_printf(b, comp_ntype(c, id) == TY_POLY
                        ? "; sp_poly_flo_domain_ck(_t%d); sp_box_f_to_int(_t%d); })"
                        : "; sp_poly_flo_domain_ck(_t%d); sp_float_fit_i(_t%d); })", tf, tf);
