        int t = ++g_tmp;
        buf_printf(b, "({ sp_%sArray *_t%d = sp_%sArray_new(); SP_GC_ROOT(_t%d); sp_%sArray_push(_t%d, ", ak, t, ak, t, ak, t);
        if (at == TY_INT) emit_int_expr(c, av[0], b);
        else if (at == TY_FLOAT) emit_float_expr(c, av[0], b);
